function totalNQueens(n) {
  let count = 0;
  const cols = new Array(n).fill(-1);
  function isValid(row, col) {
    for (let r = 0; r < row; r++) {
      const c = cols[r];
      if (c === col || Math.abs(r - row) === Math.abs(c - col)) {
        return false;
      }
    }
    return true;
  }
  function solve(row) {
    if (row === n) {
      count++;
      return;
    }
    for (let col = 0; col < n; col++) {
      if (isValid(row, col)) {
        cols[row] = col;
        solve(row + 1);
        cols[row] = -1;
      }
    }
  }
  solve(0);
  return count;
}

function totalNQueens(n) {
  let count = 0;
  function solve(row, cols, diag1, diag2) {
    if (row === n) {
      count++;
      return;
    }
    let available = ((1 << n) - 1) & ~(cols | diag1 | diag2);
    while (available !== 0) {
      const bit = available & -available;
      available ^= bit;
      solve(row + 1, cols | bit, (diag1 | bit) << 1, (diag2 | bit) >> 1);
    }
  }
  solve(0, 0, 0, 0);
  return count;
}

def totalNQueens(n: int) -> int:
    cols = [-1] * n
    count = 0

    def is_valid(row: int, col: int) -> bool:
        for r in range(row):
            c = cols[r]
            if c == col or abs(r - row) == abs(c - col):
                return False
        return True

    def solve(row: int) -> None:
        nonlocal count
        if row == n:
            count += 1
            return
        for col in range(n):
            if is_valid(row, col):
                cols[row] = col
                solve(row + 1)
                cols[row] = -1

    solve(0)
    return count
